private void backtrack(int[] a, int start, List<Integer> cur, List<List<Integer>> out) {
  if (cur.size() == a.length) { out.add(new ArrayList<>(cur)); return; }
  for (int i = start; i < a.length; i++) {
    cur.add(a[i]);            // choose
    backtrack(a, i + 1, cur, out);
    cur.remove(cur.size() - 1); // undo
  }
}

