// Fenwick: one based, lowbit walk
class Fenwick {
  int[] bit;
  Fenwick(int n) { bit = new int[n + 1]; }
  void add(int i, int v) {
    for (; i < bit.length; i += i & -i) bit[i] += v;
  }
  int sum(int i) {
    int s = 0;
    for (; i > 0; i -= i & -i) s += bit[i];
    return s;
  }
  int range(int l, int r) { return sum(r) - sum(l - 1); }
}

snippets.python:
class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)
    def add(self, i, v):
        while i <= self.n:
            self.bit[i] += v
            i += i & -i
    def prefix(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s
    def range(self, l, r):
        return self.prefix(r) - self.prefix(l - 1)

snippets.cpp:
class Fenwick {
  int n; std::vector<long long> bit;
 public:
  explicit Fenwick(int n) : n(n), bit(n + 1, 0) {}
  void add(int i, long long v) {
    for (; i <= n; i += i & -i) bit[i] += v;
  }
  long long prefix(int i) const {
    long long s = 0;
    for (; i > 0; i -= i & -i) s += bit[i];
    return s;
  }
  long long range(int l, int r) const { return prefix(r) - prefix(l - 1); }
};

