  int i = lo, j = hi;
  while (i <= j) {
    while (a[i] < pivot) ++i;
    while (a[j] > pivot) --j;
    if (i <= j) { swap(a[i], a[j]); ++i; --j; }
  }
  if (target <= j) hi = j;
  else if (target >= i) lo = i;
  else break;
}
return a[target];

