int partition(vector<int>& a, int lo, int hi) {
  int mid = lo + (hi - lo) / 2;
  int pivot = std::max(std::min(a[lo], a[mid]), std::min(std::max(a[lo], a[mid]), a[hi]));
  int i = lo, j = hi;
  while (i <= j) {
    while (a[i] < pivot) ++i;
    while (a[j] > pivot) --j;
    if (i <= j) { swap(a[i], a[j]); ++i; --j; }
  }
  return j;
}
void qsort(vector<int>& a, int lo, int hi) {
  while (lo < hi) {
    int p = partition(a, lo, hi);
    if (p - lo < hi - p) { qsort(a, lo, p - 1); lo = p + 1; }
    else { qsort(a, p + 1, hi); hi = p - 1; }
  }
}
