 public:
  NumArray(std::vector<int>& nums) : pre(nums.size() + 1, 0) {
    for (size_t i = 0; i < nums.size(); ++i) pre[i+1] = pre[i] + nums[i];
  }
  void update(int i, int v) {
    int delta = v - (pre[i+1] - pre[i]);
    for (size_t j = i + 1; j < pre.size(); ++j) pre[j] += delta;
  }
  int sumRange(int l, int r) const { return pre[r+1] - pre[l]; }
};

