code.python:
def __init__(self, nums):
    self.nums = list(nums)
    self.n = len(nums)
    self.bit = [0] * (self.n + 1)
    for i, v in enumerate(self.nums):
        self._add(i + 1, v)

def _add(self, i, v):
    while i <= self.n:
        self.bit[i] += v
        i += i & -i

def _prefix(self, i):
    s = 0
    while i > 0:
        s += self.bit[i]
        i -= i & -i
    return s

def update(self, i, v):
    self._add(i + 1, v - self.nums[i])
    self.nums[i] = v

def sumRange(self, l, r): return self._prefix(r + 1) - self._prefix(l)

