class NumArray {
  int n; std::vector<int> bit, orig;
  void add(int i, int v) { for (; i <= n; i += i & -i) bit[i] += v; }
  int prefix(int i) const { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }
 public:
  NumArray(std::vector<int>& a) : n((int)a.size()), bit(n + 1, 0), orig(a) {
    for (int i = 0; i < n; ++i) add(i + 1, a[i]);
  }
  void update(int i, int v) { add(i + 1, v - orig[i]); orig[i] = v; }
  int sumRange(int l, int r) const { return prefix(r + 1) - prefix(l); }
};
